INSERT INTO "gamedata"."ov_rollmsg" ("row_no", "level_area", "sub_seq_id", "interval_", "msg") VALUES
  (0, 1, 12, 1, '【提示】需要存储物品的朋友，可以去找村子里的仓库保管员。'),
  (1, 1, 2, 1, '【提示】刚进入游戏的新手朋友们，大家可以去和指导员仙子们聊聊天，有小礼物派送哦！'),
  (10, 1, 11, 1, '【提示】需要拜师的朋友，可以去找桃源村的桃树仙和长乐村的柳树仙。'),
  (11, 1, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (12, 1, 13, 1, '【提示】需要免费治疗的朋友，可以去找桃源东村和西村的妙仙子，或者长乐东村和西村的善仙子。'),
  (13, 1, 14, 1, '【提示】想去其它新手村的朋友，可以去找飞空艇仙子。'),
  (14, 1, 15, 1, '【提示】单击Alt+R，你可以坐下，此时体力和法力的回复速度会比站立时更快一些。'),
  (15, 1, 16, 1, '【提示】当您达到10级的时候，可以去龙城就职。职业分为五种：战士、剑客、刺客、药师和术士。'),
  (16, 2, 2, 1, '【提示】没有就职的朋友，可以去龙城找钟离门人裴谌(254,106) 就职战士，就职后可学习战士专用技能。'),
  (17, 2, 3, 1, '【提示】没有就职的朋友，可以去龙城找吕仙门人许栖岩(293,138)就职剑客，就职后可学习剑客专用技能。'),
  (18, 2, 4, 1, '【提示】没有就职的朋友，可以去龙城找仙姑门人萼绿华(242,141)就职刺客，就职后可学习刺客专用技能。'),
  (19, 2, 5, 1, '【提示】没有就职的朋友，可以去龙城找铁拐门人蓟子训(219,188)就职药师，就职后可学习药师专用技能。'),
  (2, 1, 3, 1, '【提示】在屏幕右上角的小地图里，可以查看到NPC、玩家本人和队友的位置。'),
  (20, 2, 6, 1, '【提示】没有就职的朋友，可以去龙城找果老门人寒山子(142,122)就职术士，就职后可学习术士专用技能。'),
  (21, 2, 7, 1, '【提示】在龙城的鬼谷先生(169,123)、出云城的无妄老人(173,92)、天都的白羽书仙萧洞玄(368,141)和楼兰城的先知风涯(245,100)可以购买到技能书。'),
  (22, 2, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (23, 2, 8, 1, '【提示】10级的朋友，可以去找龙城的巧匠左慈(236,154)、出云城的一道师匠(333,81)、天都的鲁班神匠(71,92)和楼兰城的工匠塔赫(185,43)学习挖矿和开店。'),
  (24, 2, 9, 1, '【提示】11级的朋友，可以捕捉和饲养自己的宠物了。'),
  (25, 2, 10, 1, '【提示】12级的朋友，可以去找龙城的巧匠左慈(236,154)、出云城的一道师匠(333,81)、天都的鲁班神匠(71,92)和楼兰城的工匠塔赫(185,43)学习钓鱼。'),
  (26, 2, 11, 1, '【提示】12级的朋友，可以在龙城的城主成隍(239,87)、出云城的执事官徐福(253,105)、天都的玉皇大帝(232,117)和楼兰城的监城官哈亚图(198,127)处申请加入家族。'),
  (27, 2, 12, 1, '【提示】15级的朋友，可以去找龙城的巧匠左慈(236,154)、出云城的一道师匠(333,81)、天都的鲁班神匠(71,92)和楼兰城的工匠塔赫(185,43)学习装备的加工与镶嵌。'),
  (28, 2, 13, 1, '【提示】15级的朋友，可以去找龙城的巧匠左慈(236,154)、出云城的一道师匠(333,81)、天都的鲁班神匠(71,92)和楼兰城的工匠塔赫(185,43)学习如何合成矿石。'),
  (29, 3, 5, 2, '【提示】没有就职的朋友，可以去龙城找铁拐门人蓟子训(219,188)就职药师，就职后可学习药师专用技能。'),
  (3, 1, 4, 1, '【提示】使用快捷键Alt+ +/-，可以放大和缩小小地图。'),
  (30, 3, 2, 2, '【提示】没有就职的朋友，可以去龙城找钟离门人裴谌(254,106) 就职战士，就职后可学习战士专用技能。'),
  (31, 3, 3, 2, '【提示】没有就职的朋友，可以去龙城找吕仙门人许栖岩(293,138)就职剑客，就职后可学习剑客专用技能。'),
  (32, 3, 4, 2, '【提示】没有就职的朋友，可以去龙城找仙姑门人萼绿华(242,141)就职刺客，就职后可学习刺客专用技能。'),
  (33, 3, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (34, 3, 6, 2, '【提示】没有就职的朋友，可以去龙城找果老门人寒山子(142,122)就职术士，就职后可学习术士专用技能。'),
  (35, 3, 7, 1, '【提示】20级的朋友，可以去找龙城的巧匠左慈(236,154)、出云城的一道师匠(333,81)、天都的鲁班神匠(71,92)和楼兰城的工匠塔赫(185,43)学习如何合成装备。'),
  (36, 3, 8, 1, '【提示】20级的朋友，可以使用幻化卡让你的宠物变变变！'),
  (37, 4, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (38, 4, 2, 2, '【提示】30级的朋友，如果你的宠物具备了坐骑的能力，你就可以骑宠啦！'),
  (39, 4, 3, 2, '【提示】30级的朋友，可以在龙城的观音院主持无恙(312,116)、出云城的无妄老人(173,92)、天都的白羽书仙萧洞玄(368,141)和楼兰城的先知风涯(245,100)处登记收徒。'),
  (4, 1, 5, 1, '【提示】左键单击小地图，可以打开当前地图的缩略图。'),
  (40, 5, 2, 2, '【提示】40级的朋友，可以在龙城的城主成隍(239,87)、出云城的执事官徐福(253,105)、天都的玉皇大帝(232,117)和楼兰城的监城官哈亚图(198,127)处申请创建自己的家族。'),
  (41, 5, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (42, 6, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (43, 7, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (44, 8, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (45, 9, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (46, 10, 1, 1, '【提示】欢迎来到幻想世界，点击F12键，您可以查看所需的任何帮助哦！'),
  (5, 1, 6, 1, '【提示】5级以下的朋友，适合去桃源村以北的芳草林和长乐村以南的吟松谷练级。'),
  (6, 1, 7, 1, '【提示】5级以上的朋友，适合去桃源村以南的桃源和长乐村以北的阳泉平原练级。'),
  (7, 1, 8, 1, '【提示】需要买药和食物的朋友，可以去找村里的道具商人。'),
  (8, 1, 9, 1, '【提示】需要买武器的朋友，可以去找村里的武器师匠。'),
  (9, 1, 10, 1, '【提示】需要买衣服鞋帽的朋友，可以去找村里的防具师匠。')
